interface ErrorStepProps {
  error: string;
  onRetry: () => void;
  onCancel?: () => void;
}

export function ErrorStep({ error, onRetry, onCancel }: ErrorStepProps) {
  return (
    <div className="cedros-deposit-flow-step cedros-deposit-flow-step-centered">
      <div className="cedros-deposit-flow-error-icon">✕</div>
      <h4 className="cedros-deposit-flow-step-title">Deposit Failed</h4>
      <p className="cedros-deposit-flow-error-message">{error}</p>

      <div className="cedros-deposit-flow-actions">
        {onCancel && (
          <button
            type="button"
            className="cedros-deposit-flow-button cedros-deposit-flow-button-secondary"
            onClick={onCancel}
          >
            Cancel
          </button>
        )}
        <button
          type="button"
          className="cedros-deposit-flow-button cedros-deposit-flow-button-primary"
          onClick={onRetry}
        >
          Try Again
        </button>
      </div>
    </div>
  );
}
