import { useCallback, useState } from 'react';
import { useAccountDeletion } from '../../hooks/useAccountDeletion';
import { ErrorMessage } from '../shared/ErrorMessage';
import { LoadingSpinner } from '../shared/LoadingSpinner';

const DELETE_CONFIRM_TEXT = 'DELETE';

export interface DeleteAccountSectionProps {
  onDeleted?: () => void;
  className?: string;
}

export function DeleteAccountSection({
  onDeleted,
  className = '',
}: DeleteAccountSectionProps) {
  const { deleteAccount, accountDeletionUrl, isLoading, error, clearError } = useAccountDeletion();
  const [confirmText, setConfirmText] = useState('');
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const handleDelete = useCallback(async () => {
    const confirmed = window.confirm(
      'This permanently removes your login profile and signs you out. Financial and audit records required by law may still be retained. Continue?'
    );
    if (!confirmed) return;

    setSuccessMessage(null);
    await deleteAccount(confirmText);
    setSuccessMessage('Your account has been deleted.');
    onDeleted?.();
  }, [confirmText, deleteAccount, onDeleted]);

  return (
    <section className={`cedros-account-delete ${className}`}>
      <div className="cedros-account-delete-header">
        <div>
          <h3 className="cedros-account-delete-title">Delete account</h3>
          <p className="cedros-account-delete-description">
            Remove this login profile from the app. Sessions, passkeys, MFA, API keys, and linked
            Apple credentials will be revoked.
          </p>
        </div>
        <a
          className="cedros-account-delete-link"
          href={accountDeletionUrl}
          target="_blank"
          rel="noreferrer"
        >
          Hosted deletion portal
        </a>
      </div>

      <div className="cedros-warning-box cedros-account-delete-warning">
        <div className="cedros-warning-content">
          <strong>Before you continue</strong>
          <p>
            Type <code>{DELETE_CONFIRM_TEXT}</code> to confirm. Organization ownership may need to
            be transferred first, and records required for financial or legal compliance may be
            retained in anonymized form.
          </p>
        </div>
      </div>

      {error && <ErrorMessage error={error} onDismiss={clearError} />}
      {successMessage && <div className="cedros-account-delete-success">{successMessage}</div>}

      <label className="cedros-label" htmlFor="cedros-delete-account-confirm">
        Confirmation text
      </label>
      <input
        id="cedros-delete-account-confirm"
        className="cedros-input"
        type="text"
        autoComplete="off"
        spellCheck={false}
        placeholder={DELETE_CONFIRM_TEXT}
        value={confirmText}
        onChange={(event) => setConfirmText(event.target.value)}
        disabled={isLoading}
      />
      <p className="cedros-account-delete-hint">
        Use the hosted deletion portal if the user is already signed out and still needs the public
        deletion path required by Google Play.
      </p>

      <div className="cedros-account-delete-actions">
        <button
          type="button"
          className="cedros-button cedros-button-danger"
          onClick={() => {
            void handleDelete();
          }}
          disabled={isLoading || confirmText.trim() !== DELETE_CONFIRM_TEXT}
        >
          {isLoading ? (
            <>
              <LoadingSpinner size="sm" />
              <span>Deleting account...</span>
            </>
          ) : (
            'Delete account'
          )}
        </button>
      </div>
    </section>
  );
}
