/**
 * Sign-mode confirm step: amount slider + token selection + deposit address display.
 */
import { useState, useEffect } from 'react';
import { TieredAmountSlider } from '../../TieredAmountSlider';
import { getTierForAmount } from '../../tierUtils';
import type { Token } from '../../tokens';
import type { DepositConfigResponse } from '../../../../types/deposit';
import { getTotalFeeUsd, formatFeeTooltip } from '../feeUtils';
import { SOL_TOKEN, OTHER_TOKEN, MAX_DEPOSIT_USD, getTokenUsdPrice, formatTokenAmount } from '../tokenUtils';
import { TokenQuickSelector } from '../TokenQuickSelector';
import type { CurrencyMode } from '../types';

interface ConfirmStepProps {
  token: Token;
  tokens: Token[];
  quickActionSymbols: string[];
  customTokenSymbols: string[];
  currencyMode: CurrencyMode;
  minAmount: number;
  maxAmount: number;
  depositAddress: string | null;
  walletReady: boolean;
  needsUnlock: boolean;
  copied: boolean;
  isListening: boolean;
  config: DepositConfigResponse;
  onCopy: () => void;
  onTokenSelect: (token: Token) => void;
  onUnlockRequired?: () => void;
  onConfirm: (amount: number, token: Token) => void;
  onBack: () => void;
  onCancel?: () => void;
}

export function ConfirmStep({
  token,
  tokens,
  quickActionSymbols,
  customTokenSymbols,
  currencyMode,
  minAmount,
  maxAmount,
  depositAddress,
  walletReady,
  needsUnlock,
  copied,
  isListening,
  config,
  onCopy,
  onTokenSelect,
  onUnlockRequired,
  onConfirm,
  onBack,
}: ConfirmStepProps) {
  const [amountUsd, setAmountUsd] = useState(config.privateMinUsd);
  const [feeTooltipOpen, setFeeTooltipOpen] = useState(false);
  // Track the token selected before auto-switching to SOL for micro tier
  const [preMicroToken, setPreMicroToken] = useState<Token | null>(null);

  const tier = getTierForAmount(amountUsd, config);
  const isMicroTier = tier === 'sol_micro';
  const isOtherToken = token.symbol === OTHER_TOKEN.symbol;

  const totalFeeUsd = getTotalFeeUsd(config, amountUsd);
  // H-08: Don't floor zero fees to $0.01
  const feeTotalDisplay = totalFeeUsd === 0 ? 0 : totalFeeUsd < 0.01 ? 0.01 : totalFeeUsd;
  const feeLine = isOtherToken
    ? 'Fees: calculated after deposit'
    : totalFeeUsd === 0
      ? 'No fees'
      : `Fees: $${feeTotalDisplay.toFixed(2)} total`;
  const feeTooltip = isOtherToken ? '' : formatFeeTooltip(config, amountUsd, totalFeeUsd);

  const tokenUsdPrice = getTokenUsdPrice(isMicroTier ? SOL_TOKEN : token, config);
  const tokenAmount = tokenUsdPrice
    ? amountUsd / tokenUsdPrice
    : token.symbol === 'SOL' && config.solPriceUsd > 0
      ? amountUsd / config.solPriceUsd
      : null; // R2-H13: Don't use raw USD as token amount when price is unknown
  const sendAmountLabel = tokenAmount != null
    ? formatTokenAmount(tokenAmount, isMicroTier ? 'SOL' : token.symbol)
    : null;

  const netAmountUsd = amountUsd - totalFeeUsd;
  const feesExceedAmount = netAmountUsd <= 0 && amountUsd > 0;

  const isValidAmount =
    !isOtherToken &&
    amountUsd > 0 &&
    !feesExceedAmount &&
    tokenAmount != null &&
    tokenAmount >= minAmount &&
    tokenAmount <= maxAmount;

  // Auto-select SOL for micro tier, restore previous token when leaving micro tier
  useEffect(() => {
    if (currencyMode !== 'multi-token') return;

    if (isMicroTier && token.symbol !== 'SOL') {
      setPreMicroToken(token);
      const solToken = tokens.find((t) => t.symbol === 'SOL');
      if (solToken) onTokenSelect(solToken);
    } else if (!isMicroTier && preMicroToken && token.symbol === 'SOL') {
      onTokenSelect(preMicroToken);
      setPreMicroToken(null);
    }
  }, [isMicroTier, token.symbol, currencyMode, tokens, onTokenSelect, preMicroToken, token]);

  const handleConfirm = () => {
    if (isValidAmount && tokenAmount != null) {
      onConfirm(tokenAmount, token);
    }
  };

  return (
    <div className="cedros-deposit-flow-step">
      <h4 className="cedros-deposit-flow-step-title">Choose Amount</h4>
      <p className="cedros-deposit-flow-step-desc">
        Set how much you want to deposit. Higher tiers unlock privacy.
      </p>

      {/* Token Selector - only show for non-micro tiers in multi-token mode */}
      {currencyMode === 'multi-token' && !isMicroTier && (
        <TokenQuickSelector
          token={token}
          tokens={tokens}
          quickActionSymbols={quickActionSymbols}
          customTokenSymbols={customTokenSymbols}
          onTokenSelect={onTokenSelect}
        />
      )}

      {/* Amount Selector with Tier Indicator */}
      <div className="cedros-deposit-flow-field">
        <TieredAmountSlider
          config={config}
          valueUsd={amountUsd}
          onChange={setAmountUsd}
          maxUsd={MAX_DEPOSIT_USD}
        />
      </div>

      {/* Deposit Address */}
      <div className="cedros-deposit-flow-field">
        <label className="cedros-deposit-flow-label">
          {isOtherToken
            ? 'Sign to send tokens to this address'
            : `Sign to send ${sendAmountLabel ?? '--'} ${isMicroTier ? 'SOL' : token.symbol} to this address`}
        </label>
        <div className="cedros-deposit-flow-address-box">
          <code className="cedros-deposit-flow-address">{depositAddress || 'Loading...'}</code>
          <div className="cedros-deposit-flow-address-actions">
            <button
              type="button"
              className="cedros-deposit-flow-copy-btn cedros-deposit-flow-copy-icon"
              onClick={onCopy}
              title="Copy address"
              disabled={!depositAddress}
            >
              {copied ? '✓' : '⧉'}
            </button>
            {depositAddress && (
              <a
                className="cedros-deposit-flow-copy-btn cedros-deposit-flow-copy-link cedros-deposit-flow-copy-icon"
                href={`https://orbmarkets.io/account/${depositAddress}`}
                target="_blank"
                rel="noopener noreferrer"
                title="View on Orb Markets"
              >
                ↗
              </a>
            )}
          </div>
        </div>
        {copied && <p className="cedros-deposit-flow-copied-msg">Copied!</p>}
      </div>

      {feesExceedAmount && (
        <div className="cedros-deposit-flow-warning">
          <p>Deposit amount is less than the fees. Increase the amount to proceed.</p>
        </div>
      )}

      <div className="cedros-deposit-flow-info-stack">
        <div className="cedros-deposit-flow-info-item">
          <span className="cedros-deposit-flow-info-dot" />
          <span>Send only on the Solana network.</span>
        </div>
        <div className="cedros-deposit-flow-info-item">
          <span className="cedros-deposit-flow-info-dot" />
          <span>
            {feeLine}
            <button
              type="button"
              className={`cedros-deposit-flow-fee-info ${feeTooltipOpen ? 'is-open' : ''}`}
              data-tooltip={feeTooltip}
              aria-label={`Fee breakdown: ${feeTooltip.replaceAll('\n', ', ')}`}
              aria-expanded={feeTooltipOpen}
              onClick={(event) => {
                event.stopPropagation();
                setFeeTooltipOpen((current) => !current);
              }}
              onBlur={() => setFeeTooltipOpen(false)}
              onKeyDown={(event) => {
                if (event.key === 'Escape') {
                  setFeeTooltipOpen(false);
                }
              }}
            >
              i
            </button>
          </span>
        </div>
        <div className="cedros-deposit-flow-info-item">
          <span className="cedros-deposit-flow-info-dot" />
          <span>Credits appear after network confirmation.</span>
        </div>
      </div>

      {isListening && (
        <div className="cedros-deposit-flow-info-banner">
          Listening for incoming transfers. We will confirm automatically.
        </div>
      )}

      {needsUnlock && (
        <div className="cedros-deposit-flow-warning">
          <p>Your wallet is locked. Unlock it to continue.</p>
          {onUnlockRequired && (
            <button
              type="button"
              className="cedros-deposit-flow-button cedros-deposit-flow-button-secondary"
              onClick={onUnlockRequired}
            >
              Unlock Wallet
            </button>
          )}
        </div>
      )}

      <div className="cedros-deposit-flow-actions">
        <button
          type="button"
          className="cedros-deposit-flow-button cedros-deposit-flow-button-secondary"
          onClick={onBack}
        >
          Back
        </button>
        <button
          type="button"
          className="cedros-deposit-flow-button cedros-deposit-flow-button-primary"
          onClick={handleConfirm}
          disabled={!isValidAmount || !walletReady || !depositAddress}
        >
          Deposit
        </button>
      </div>
    </div>
  );
}
