import { useState, useCallback, useMemo } from 'react';
import { useCedrosLogin } from '../context/useCedrosLogin';
import { ApiClient } from '../utils/apiClient';

interface KycStatusResponse {
  status: string;
  verifiedAt?: string;
  expiresAt?: string;
  enforcementMode: string;
}

interface KycStartResponse {
  sessionId: string;
  redirectUrl: string;
}

/**
 * Return type for the useKyc hook
 */
export interface UseKycReturn {
  /** Current KYC status: none, pending, verified, failed, expired, canceled */
  status: string | null;
  /** When verification was completed (ISO 8601) */
  verifiedAt: string | null;
  /** When verification expires (ISO 8601) */
  expiresAt: string | null;
  /** Whether KYC enforcement is active (mode is not "none") */
  isRequired: boolean;
  /** Current enforcement mode from server */
  enforcementMode: string | null;
  /** Fetch the current user's KYC status */
  fetchStatus: () => Promise<KycStatusResponse>;
  /** Start a new verification session (returns redirect URL) */
  startVerification: () => Promise<string>;
  /** Whether a request is in progress */
  isLoading: boolean;
  /** Error from the last operation */
  error: Error | null;
}

/**
 * Hook for KYC identity verification.
 *
 * @example
 * ```tsx
 * const { status, isRequired, startVerification, fetchStatus, isLoading } = useKyc();
 *
 * useEffect(() => { fetchStatus(); }, [fetchStatus]);
 *
 * if (isRequired && status !== 'verified') {
 *   const url = await startVerification();
 *   window.location.href = url;
 * }
 * ```
 */
export function useKyc(): UseKycReturn {
  const { config, _internal } = useCedrosLogin();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [verifiedAt, setVerifiedAt] = useState<string | null>(null);
  const [expiresAt, setExpiresAt] = useState<string | null>(null);
  const [enforcementMode, setEnforcementMode] = useState<string | null>(null);

  const isRequired = enforcementMode !== null && enforcementMode !== 'none';

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        getAccessToken: _internal?.getAccessToken,
      }),
    [config.serverUrl, config.requestTimeout, _internal]
  );

  const fetchStatus = useCallback(async (): Promise<KycStatusResponse> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.get<KycStatusResponse>('/kyc/status', {
        credentials: 'include',
      });
      setStatus(resp.status);
      setVerifiedAt(resp.verifiedAt ?? null);
      setExpiresAt(resp.expiresAt ?? null);
      setEnforcementMode(resp.enforcementMode);
      return resp;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  const startVerification = useCallback(async (): Promise<string> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.post<KycStartResponse>(
        '/kyc/start',
        undefined,
        { credentials: 'include' }
      );
      setStatus('pending');
      return resp.redirectUrl;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  return {
    status,
    verifiedAt,
    expiresAt,
    isRequired,
    enforcementMode,
    fetchStatus,
    startVerification,
    isLoading,
    error,
  };
}
