import { useEffect, useCallback, useState } from 'react';
import { useAccessCodes } from '../hooks/useAccessCodes';
import type { AccessCode } from '../hooks/useAccessCodes';

// ---- helpers ----------------------------------------------------------------

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return iso;
  }
}

function codeStatus(code: AccessCode): 'active' | 'used' | 'expired' {
  if (code.expiresAt && new Date(code.expiresAt) < new Date()) return 'expired';
  if (code.maxUses !== null && code.currentUses >= code.maxUses) return 'used';
  return 'active';
}

// ---- status badge -----------------------------------------------------------

interface StatusBadgeProps {
  status: 'active' | 'used' | 'expired';
}

function StatusBadge({ status }: StatusBadgeProps) {
  const modifiers: Record<string, string> = {
    active: 'cedros-invite-panel__badge--active',
    used: 'cedros-invite-panel__badge--used',
    expired: 'cedros-invite-panel__badge--expired',
  };
  return (
    <span className={`cedros-invite-panel__badge ${modifiers[status] ?? ''}`}>
      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  );
}

// ---- copy button ------------------------------------------------------------

interface CopyButtonProps {
  text: string;
}

function CopyButton({ text }: CopyButtonProps) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Clipboard API not available — graceful no-op
    }
  }, [text]);

  return (
    <button
      type="button"
      className="cedros-invite-panel__copy-btn"
      onClick={handleCopy}
      aria-label={copied ? 'Copied' : `Copy code ${text}`}
      title={copied ? 'Copied!' : 'Copy to clipboard'}
    >
      {copied ? '✓' : 'Copy'}
    </button>
  );
}

// ---- props ------------------------------------------------------------------

export interface InviteCodePanelProps {
  /** Additional CSS class */
  className?: string;
}

// ---- component --------------------------------------------------------------

/**
 * User-facing panel for generating and sharing invite codes.
 *
 * Displays the user's existing invite codes (copyable, with status and dates)
 * and provides a button to generate a new one.
 *
 * @example
 * ```tsx
 * <InviteCodePanel />
 * ```
 */
export function InviteCodePanel({ className }: InviteCodePanelProps) {
  const { codes, total, generateCode, fetchCodes, isLoading, error } = useAccessCodes();
  const [generating, setGenerating] = useState(false);
  const [generateError, setGenerateError] = useState<string | null>(null);

  useEffect(() => {
    fetchCodes().catch(() => undefined);
  }, [fetchCodes]);

  const handleGenerate = useCallback(async () => {
    setGenerating(true);
    setGenerateError(null);
    try {
      await generateCode();
    } catch (err) {
      setGenerateError(err instanceof Error ? err.message : 'Failed to generate invite code.');
    } finally {
      setGenerating(false);
    }
  }, [generateCode]);

  const activeCount = codes.filter((c) => codeStatus(c) === 'active').length;

  return (
    <div
      className={`cedros-invite-panel ${className ?? ''}`.trim()}
      aria-label="Invite code panel"
    >
      {/* ---- header ---- */}
      <div className="cedros-invite-panel__header">
        <h2 className="cedros-invite-panel__title">Invite Codes</h2>
        <span className="cedros-invite-panel__budget" aria-live="polite">
          {activeCount} active · {total} total
        </span>
      </div>

      {/* ---- error banners ---- */}
      {error && (
        <div className="cedros-invite-panel__error" role="alert">
          {error.message}
        </div>
      )}
      {generateError && (
        <div className="cedros-invite-panel__error" role="alert">
          {generateError}
        </div>
      )}

      {/* ---- generate button ---- */}
      <button
        type="button"
        className="cedros-button cedros-button-primary cedros-button-md"
        onClick={handleGenerate}
        disabled={generating || isLoading}
        aria-busy={generating}
      >
        {generating ? 'Generating...' : 'Generate Invite Code'}
      </button>

      {/* ---- code list ---- */}
      <section className="cedros-invite-panel__list-section" aria-label="Your invite codes">
        {isLoading && codes.length === 0 ? (
          <div className="cedros-invite-panel__loading" aria-busy="true">
            Loading...
          </div>
        ) : codes.length === 0 ? (
          <div className="cedros-invite-panel__empty">
            No invite codes yet. Generate one above.
          </div>
        ) : (
          <div
            className="cedros-invite-panel__table-wrapper"
            role="region"
            aria-label="Invite codes table"
            tabIndex={0}
          >
            <table className="cedros-invite-panel__table">
              <thead>
                <tr>
                  <th scope="col" className="cedros-invite-panel__th">Code</th>
                  <th scope="col" className="cedros-invite-panel__th">Uses</th>
                  <th scope="col" className="cedros-invite-panel__th">Created</th>
                  <th scope="col" className="cedros-invite-panel__th">Expires</th>
                  <th scope="col" className="cedros-invite-panel__th">Status</th>
                  <th scope="col" className="cedros-invite-panel__th">
                    <span className="cedros-sr-only">Actions</span>
                  </th>
                </tr>
              </thead>
              <tbody>
                {codes.map((code) => {
                  const status = codeStatus(code);
                  const usesLabel =
                    code.maxUses !== null
                      ? `${code.currentUses} / ${code.maxUses}`
                      : `${code.currentUses}`;
                  return (
                    <tr key={code.id} className="cedros-invite-panel__tr">
                      <td className="cedros-invite-panel__td cedros-invite-panel__td--code">
                        <code className="cedros-invite-panel__code">{code.code}</code>
                      </td>
                      <td className="cedros-invite-panel__td">{usesLabel}</td>
                      <td className="cedros-invite-panel__td">{formatDate(code.createdAt)}</td>
                      <td className="cedros-invite-panel__td">
                        {code.expiresAt ? formatDate(code.expiresAt) : '—'}
                      </td>
                      <td className="cedros-invite-panel__td">
                        <StatusBadge status={status} />
                      </td>
                      <td className="cedros-invite-panel__td">
                        <CopyButton text={code.code} />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}
