import { useState, useCallback, useMemo } from 'react';
import { useCedrosLogin } from '../context/useCedrosLogin';
import { ApiClient } from '../utils/apiClient';
import type {
  AccreditationMethod,
  AccreditationStatus,
  AccreditationStatusResponse,
  AccreditationSubmissionItem,
} from '../types/accreditation';

/**
 * Return type for the useAccreditation hook.
 *
 * @example
 * ```tsx
 * const { status, isRequired, fetchStatus, submitVerification } = useAccreditation();
 *
 * useEffect(() => { fetchStatus(); }, [fetchStatus]);
 * ```
 */
export interface UseAccreditationReturn {
  /** Current accreditation status: none, pending, approved, rejected, expired */
  status: AccreditationStatus | null;
  /** When accreditation was verified (ISO 8601) */
  verifiedAt: string | null;
  /** When accreditation expires (ISO 8601) */
  expiresAt: string | null;
  /** Whether accreditation enforcement is active (mode is not "none") */
  isRequired: boolean;
  /** Current enforcement mode from server */
  enforcementMode: string | null;
  /** Fetch the current user's accreditation status */
  fetchStatus: () => Promise<AccreditationStatusResponse>;
  /**
   * Submit a new accreditation verification request.
   *
   * @param method - verification method
   * @param data - method-specific data (income amount, CRD number, etc.)
   * @returns submissionId of the created submission
   */
  submitVerification: (
    method: AccreditationMethod,
    data: Record<string, unknown>
  ) => Promise<{ submissionId: string }>;
  /**
   * Upload a supporting document for a submission.
   *
   * @param submissionId - ID of the submission to attach the document to
   * @param file - File object to upload
   * @param documentType - document category (e.g. "tax_return", "letter")
   * @returns documentId of the created document record
   */
  uploadDocument: (
    submissionId: string,
    file: File,
    documentType: string
  ) => Promise<{ documentId: string }>;
  /** List this user's accreditation submissions */
  listSubmissions: () => Promise<AccreditationSubmissionItem[]>;
  /** Whether a request is in progress */
  isLoading: boolean;
  /** Error from the last operation */
  error: Error | null;
}

/**
 * Hook for accredited investor verification.
 *
 * Follows the same pattern as useKyc.
 */
export function useAccreditation(): UseAccreditationReturn {
  const { config, _internal } = useCedrosLogin();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [status, setStatus] = useState<AccreditationStatus | null>(null);
  const [verifiedAt, setVerifiedAt] = useState<string | null>(null);
  const [expiresAt, setExpiresAt] = useState<string | null>(null);
  const [enforcementMode, setEnforcementMode] = useState<string | null>(null);

  const isRequired = enforcementMode !== null && enforcementMode !== 'none';

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        getAccessToken: _internal?.getAccessToken,
      }),
    [config.serverUrl, config.requestTimeout, _internal]
  );

  const fetchStatus = useCallback(async (): Promise<AccreditationStatusResponse> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.get<AccreditationStatusResponse>('/accreditation/status', {
        credentials: 'include',
      });
      setStatus(resp.status);
      setVerifiedAt(resp.verifiedAt ?? null);
      setExpiresAt(resp.expiresAt ?? null);
      setEnforcementMode(resp.enforcementMode);
      return resp;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  const submitVerification = useCallback(
    async (
      method: AccreditationMethod,
      data: Record<string, unknown>
    ): Promise<{ submissionId: string }> => {
      setIsLoading(true);
      setError(null);
      try {
        const resp = await apiClient.post<{ submissionId: string }>(
          '/accreditation/submit',
          { method, ...data },
          { credentials: 'include' }
        );
        setStatus('pending');
        return resp;
      } catch (err) {
        const e = err instanceof Error ? err : new Error(String(err));
        setError(e);
        throw e;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const uploadDocument = useCallback(
    async (
      submissionId: string,
      file: File,
      documentType: string
    ): Promise<{ documentId: string }> => {
      setIsLoading(true);
      setError(null);
      try {
        const formData = new FormData();
        formData.append('submissionId', submissionId);
        formData.append('documentType', documentType);
        formData.append('file', file);

        const token = _internal?.getAccessToken?.();
        const headers: Record<string, string> = {};
        if (token) {
          headers['Authorization'] = `Bearer ${token}`;
        }

        const resp = await fetch(`${config.serverUrl}/accreditation/upload`, {
          method: 'POST',
          headers,
          credentials: 'include',
          body: formData,
        });

        if (!resp.ok) {
          const text = await resp.text().catch(() => resp.statusText);
          throw new Error(`Upload failed (${resp.status}): ${text}`);
        }

        return resp.json() as Promise<{ documentId: string }>;
      } catch (err) {
        const e = err instanceof Error ? err : new Error(String(err));
        setError(e);
        throw e;
      } finally {
        setIsLoading(false);
      }
    },
    [config.serverUrl, _internal]
  );

  const listSubmissions = useCallback(async (): Promise<AccreditationSubmissionItem[]> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.get<{ submissions: AccreditationSubmissionItem[] }>(
        '/accreditation/submissions',
        { credentials: 'include' }
      );
      return resp.submissions;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  return {
    status,
    verifiedAt,
    expiresAt,
    isRequired,
    enforcementMode,
    fetchStatus,
    submitVerification,
    uploadDocument,
    listSubmissions,
    isLoading,
    error,
  };
}
