/**
 * Wallet enrollment wizard component (server-side signing)
 *
 * Auto-detects the user's auth method and shows the appropriate flow:
 * - Email users → enter existing account password
 * - Passkey users → authenticate with existing passkey
 * - OAuth-only users → set a new account password first
 *
 * Share B is stored as plaintext on the server (SSS math protects it).
 */

import { useState, useCallback, useEffect } from 'react';
import { useCedrosLogin } from '../../context/useCedrosLogin';
import { useWalletEnrollment } from '../../hooks/useWalletEnrollment';
import { useSetPassword } from '../../hooks/useSetPassword';
import { PasswordInput } from '../email/PasswordInput';
import { RecoveryPhraseDisplay } from './RecoveryPhraseDisplay';
import { validatePassword } from '../../utils/validation';

export interface WalletEnrollmentProps {
  /** Callback when enrollment completes */
  onComplete?: (solanaPubkey: string) => void;
  /** Callback to cancel enrollment */
  onCancel?: () => void;
  /** Optional class name */
  className?: string;
}

type DetectedFlow = 'password' | 'passkey' | 'set-password';

function detectFlow(authMethods: string[]): DetectedFlow {
  if (authMethods.includes('email')) return 'password';
  if (authMethods.includes('webauthn')) return 'passkey';
  return 'set-password';
}

/**
 * Wallet enrollment wizard
 */
export function WalletEnrollment({
  onComplete,
  onCancel,
  className = '',
}: WalletEnrollmentProps) {
  const { user } = useCedrosLogin();
  const {
    state,
    startEnrollmentWithPassword,
    startEnrollmentWithPasskey,
    confirmRecoveryPhrase,
    cancel,
    isEnrolling,
  } = useWalletEnrollment();
  const { setPassword: setAccountPassword, isLoading: isSettingPassword } = useSetPassword();

  const flow = user ? detectFlow(user.authMethods) : 'password';

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordError, setPasswordError] = useState<string | null>(null);

  // Reset form when user changes
  useEffect(() => {
    setPassword('');
    setConfirmPassword('');
    setPasswordError(null);
  }, [user?.id]);

  // Existing-password flow: single field, no confirm, no strength meter
  const handlePasswordSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();
      setPasswordError(null);
      await startEnrollmentWithPassword(password);
    },
    [password, startEnrollmentWithPassword]
  );

  // Set-password flow (OAuth-only): new password + confirm + strength meter
  const handleSetPasswordSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();

      if (password !== confirmPassword) {
        setPasswordError('Passwords do not match');
        return;
      }

      const validation = validatePassword(password);
      if (!validation.isValid) {
        const firstError = Object.values(validation.errors)[0];
        setPasswordError(firstError ?? 'Password does not meet requirements');
        return;
      }

      setPasswordError(null);

      try {
        // First set the account password
        await setAccountPassword(password);
        // Then use it for wallet enrollment
        await startEnrollmentWithPassword(password);
      } catch {
        // Error already set by the hook
      }
    },
    [password, confirmPassword, setAccountPassword, startEnrollmentWithPassword]
  );

  const handlePasskeySubmit = useCallback(async () => {
    await startEnrollmentWithPasskey();
  }, [startEnrollmentWithPasskey]);

  const handleRecoveryConfirm = useCallback(() => {
    confirmRecoveryPhrase();
    if (state.solanaPubkey) {
      onComplete?.(state.solanaPubkey);
    }
  }, [confirmRecoveryPhrase, state.solanaPubkey, onComplete]);

  const handleCancel = useCallback(() => {
    cancel();
    onCancel?.();
  }, [cancel, onCancel]);

  const isBusy = isEnrolling || isSettingPassword;

  // Progress states
  if (state.step === 'generating_seed' || state.step === 'splitting_shares') {
    return (
      <div className={`cedros-wallet-enrollment ${className}`} aria-busy="true">
        <div className="cedros-enrollment-progress" role="status" aria-live="polite">
          <div className="cedros-spinner" aria-hidden="true" />
          <p>Generating secure wallet...</p>
        </div>
      </div>
    );
  }

  if (state.step === 'encrypting_shares') {
    return (
      <div className={`cedros-wallet-enrollment ${className}`} aria-busy="true">
        <div className="cedros-enrollment-progress" role="status" aria-live="polite">
          <div className="cedros-spinner" aria-hidden="true" />
          <p>Encrypting wallet shares...</p>
        </div>
      </div>
    );
  }

  if (state.step === 'uploading') {
    return (
      <div className={`cedros-wallet-enrollment ${className}`} aria-busy="true">
        <div className="cedros-enrollment-progress" role="status" aria-live="polite">
          <div className="cedros-spinner" aria-hidden="true" />
          <p>Saving wallet...</p>
        </div>
      </div>
    );
  }

  if (state.step === 'showing_recovery' && state.recoveryPhrase) {
    return (
      <div className={`cedros-wallet-enrollment ${className}`}>
        <RecoveryPhraseDisplay words={state.recoveryPhrase} onConfirm={handleRecoveryConfirm} />
      </div>
    );
  }

  if (state.step === 'complete') {
    return (
      <div className={`cedros-wallet-enrollment ${className}`}>
        <div className="cedros-enrollment-complete">
          <svg
            className="cedros-success-icon"
            width="48"
            height="48"
            viewBox="0 0 48 48"
            fill="none"
            aria-hidden="true"
          >
            <circle cx="24" cy="24" r="20" stroke="currentColor" strokeWidth="2" />
            <path
              d="M16 24l6 6 12-12"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
          <h3>Wallet Created!</h3>
          <p className="cedros-pubkey">
            <strong>Address:</strong> {state.solanaPubkey}
          </p>
          <p>Your non-custodial Solana wallet is ready to use.</p>
        </div>
      </div>
    );
  }

  if (state.step === 'error') {
    return (
      <div className={`cedros-wallet-enrollment ${className}`}>
        <div className="cedros-enrollment-error">
          <svg
            className="cedros-error-icon"
            width="48"
            height="48"
            viewBox="0 0 48 48"
            fill="none"
            aria-hidden="true"
          >
            <circle cx="24" cy="24" r="20" stroke="currentColor" strokeWidth="2" />
            <path
              d="M24 16v12m0 6h.01"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
          </svg>
          <h3>Enrollment Failed</h3>
          <p className="cedros-error-message">{state.error}</p>
          <div className="cedros-error-actions">
            <button
              type="button"
              className="cedros-button cedros-button-secondary"
              onClick={handleCancel}
            >
              Cancel
            </button>
            <button
              type="button"
              className="cedros-button cedros-button-primary"
              onClick={() => cancel()}
            >
              Try Again
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Default: credential entry form (auto-detected flow)
  return (
    <div className={`cedros-wallet-enrollment ${className}`}>
      <div className="cedros-enrollment-header">
        <h2>Create Wallet</h2>
        {flow === 'password' && (
          <p>Enter your account password to secure your wallet.</p>
        )}
        {flow === 'passkey' && (
          <p>Authenticate with your passkey to secure your wallet.</p>
        )}
        {flow === 'set-password' && (
          <p>Set a password for your account to secure your wallet.</p>
        )}
      </div>

      {/* Existing-password flow (email users) */}
      {flow === 'password' && (
        <form onSubmit={handlePasswordSubmit} className="cedros-enrollment-form">
          <PasswordInput
            label="Account Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            disabled={isBusy}
            required
            placeholder="Enter your account password"
          />

          <div className="cedros-enrollment-actions">
            {onCancel && (
              <button
                type="button"
                className="cedros-button cedros-button-secondary"
                onClick={handleCancel}
                disabled={isBusy}
              >
                Cancel
              </button>
            )}
            <button
              type="submit"
              className="cedros-button cedros-button-primary"
              disabled={isBusy || !password}
            >
              {isBusy ? 'Creating...' : 'Continue'}
            </button>
          </div>
        </form>
      )}

      {/* Passkey flow (webauthn users) */}
      {flow === 'passkey' && (
        <div className="cedros-enrollment-form">
          <div className="cedros-passkey-info">
            <svg
              className="cedros-passkey-icon"
              width="48"
              height="48"
              viewBox="0 0 48 48"
              fill="none"
              aria-hidden="true"
            >
              <rect
                x="8"
                y="16"
                width="32"
                height="24"
                rx="4"
                stroke="currentColor"
                strokeWidth="2"
              />
              <circle cx="24" cy="28" r="4" stroke="currentColor" strokeWidth="2" />
              <path d="M24 32v4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
            <p>Use your passkey (Touch ID, Face ID, or Windows Hello) to secure your wallet.</p>
          </div>

          <div className="cedros-enrollment-actions">
            {onCancel && (
              <button
                type="button"
                className="cedros-button cedros-button-secondary"
                onClick={handleCancel}
                disabled={isBusy}
              >
                Cancel
              </button>
            )}
            <button
              type="button"
              className="cedros-button cedros-button-primary"
              onClick={handlePasskeySubmit}
              disabled={isBusy}
            >
              {isBusy ? 'Creating...' : 'Use Passkey'}
            </button>
          </div>
        </div>
      )}

      {/* Set-password flow (OAuth-only users) */}
      {flow === 'set-password' && (
        <form onSubmit={handleSetPasswordSubmit} className="cedros-enrollment-form">
          <PasswordInput
            label="New Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            showStrengthMeter
            disabled={isBusy}
            required
            minLength={8}
            placeholder="Choose a strong password"
          />

          <PasswordInput
            label="Confirm Password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            error={passwordError ?? undefined}
            disabled={isBusy}
            required
            minLength={8}
            placeholder="Confirm your password"
          />

          <div className="cedros-password-info">
            <p>This password will also be used to sign transactions.</p>
          </div>

          <div className="cedros-enrollment-actions">
            {onCancel && (
              <button
                type="button"
                className="cedros-button cedros-button-secondary"
                onClick={handleCancel}
                disabled={isBusy}
              >
                Cancel
              </button>
            )}
            <button
              type="submit"
              className="cedros-button cedros-button-primary"
              disabled={isBusy || !password || !confirmPassword}
            >
              {isBusy ? 'Creating...' : 'Continue'}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}
