import { useState, useCallback, useMemo } from 'react';
import { useCedrosLogin } from '../context/useCedrosLogin';
import { ApiClient } from '../utils/apiClient';

/**
 * A single access code record as returned by the server.
 */
export interface AccessCode {
  id: string;
  code: string;
  codeType: string;
  maxUses: number | null;
  currentUses: number;
  expiresAt: string | null;
  createdAt: string;
}

interface AccessCodeListResponse {
  items: AccessCode[];
  total: number;
}

/**
 * Return type for the useAccessCodes hook.
 *
 * Inputs: none (reads config from CedrosLoginProvider context)
 * Outputs: user's generated codes and mutation methods
 * Errors: all methods throw on failure and set `error` state
 * Invariants: `isLoading` is true only while a request is in flight
 */
export interface UseAccessCodesReturn {
  /** Generated codes by this user */
  codes: AccessCode[];
  /** Total number of codes on server */
  total: number;
  /** Generate a new invite code */
  generateCode: () => Promise<AccessCode>;
  /** Fetch user's generated codes */
  fetchCodes: () => Promise<void>;
  /** Whether a request is in progress */
  isLoading: boolean;
  /** Error from the last operation */
  error: Error | null;
}

/**
 * Hook for user-facing access code operations.
 *
 * Lets authenticated users generate invite codes and view the ones they've
 * already created.
 *
 * @example
 * ```tsx
 * const { codes, generateCode, fetchCodes, isLoading, error } = useAccessCodes();
 *
 * useEffect(() => { fetchCodes(); }, [fetchCodes]);
 *
 * const handleGenerate = async () => {
 *   const code = await generateCode();
 *   console.log(code.code);
 * };
 * ```
 */
export function useAccessCodes(): UseAccessCodesReturn {
  const { config, _internal } = useCedrosLogin();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [codes, setCodes] = useState<AccessCode[]>([]);
  const [total, setTotal] = useState(0);

  const apiClient = useMemo(
    () =>
      new ApiClient({
        baseUrl: config.serverUrl,
        timeoutMs: config.requestTimeout,
        getAccessToken: _internal?.getAccessToken,
      }),
    [config.serverUrl, config.requestTimeout, _internal]
  );

  const generateCode = useCallback(async (): Promise<AccessCode> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.post<AccessCode>(
        '/access-codes/generate',
        {},
        { credentials: 'include' }
      );
      setCodes((prev) => [resp, ...prev]);
      setTotal((prev) => prev + 1);
      return resp;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  const fetchCodes = useCallback(async (): Promise<void> => {
    setIsLoading(true);
    setError(null);
    try {
      const resp = await apiClient.get<AccessCodeListResponse>('/access-codes/mine', {
        credentials: 'include',
      });
      setCodes(resp.items);
      setTotal(resp.total);
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  return {
    codes,
    total,
    generateCode,
    fetchCodes,
    isLoading,
    error,
  };
}
