import { useState } from 'react';
import type { Token } from '../../tokens';
import { getPurchaseCurrencyLabel } from '../tokenUtils';
import type { CurrencyMode, DepositMethod } from '../types';

interface UnlockStepProps {
  token: Token;
  tokens: Token[];
  currencyMode: CurrencyMode;
  depositMethod: DepositMethod;
  isAuthorizing: boolean;
  error: string | null;
  onAuthorize: (password: string) => void;
  onBack?: () => void;
  onCancel?: () => void;
}

export function UnlockStep({
  token,
  tokens,
  currencyMode,
  depositMethod,
  isAuthorizing,
  error,
  onAuthorize,
  onBack,
}: UnlockStepProps) {
  const [password, setPassword] = useState('');
  const purchaseCurrencyLabel = getPurchaseCurrencyLabel(currencyMode, token, tokens);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (password.trim()) {
      onAuthorize(password);
      setPassword(''); // R2-M14: Clear password from component state after submission
    }
  };

  return (
    <div className="cedros-deposit-flow-step">
      <h4 className="cedros-deposit-flow-step-title">Authorize Deposit</h4>
      <p className="cedros-deposit-flow-step-desc">
        {depositMethod === 'sign'
          ? currencyMode === 'multi-token'
            ? 'Enter your password to authorize a deposit. This allows us to process your withdrawal when the privacy period ends.'
            : `Enter your password to authorize a ${purchaseCurrencyLabel} deposit. This allows us to process your withdrawal when the privacy period ends.`
          : currencyMode === 'multi-token'
            ? 'Enter your password to get your deposit address. Any supported token sent to this address will be credited to your account.'
            : `Enter your password to get your deposit address. Any ${purchaseCurrencyLabel} sent to this address will be credited to your account.`}
      </p>

      <form onSubmit={handleSubmit}>
        <div className="cedros-deposit-flow-field">
          <label className="cedros-deposit-flow-label" htmlFor="deposit-password">
            Password
          </label>
          <input
            id="deposit-password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="cedros-deposit-flow-input"
            placeholder="Enter your password"
            disabled={isAuthorizing}
            autoComplete="current-password"
          />
        </div>

        {error && <p className="cedros-deposit-flow-error">{error}</p>}

        <div className="cedros-deposit-flow-actions">
          <button
            type="button"
            className="cedros-deposit-flow-button cedros-deposit-flow-button-secondary"
            onClick={onBack}
            disabled={isAuthorizing}
          >
            Back
          </button>
          <button
            type="submit"
            className="cedros-deposit-flow-button cedros-deposit-flow-button-primary"
            disabled={!password.trim() || isAuthorizing}
          >
            {isAuthorizing ? 'Authorizing...' : 'Continue'}
          </button>
        </div>
      </form>
    </div>
  );
}
