import { useEffect, useRef, useState } from 'react';

export interface KycCallbackProps {
  /** Function that fetches KYC status — obtain from useKyc().fetchStatus */
  fetchStatus: () => Promise<{ status: string }>;
  /** Called when polling resolves to a non-pending status */
  onComplete?: (status: string) => void;
  /** Additional CSS classes */
  className?: string;
}

const POLL_INTERVAL_MS = 3_000;
const POLL_TIMEOUT_MS = 60_000;

function messageForStatus(status: string): string {
  switch (status) {
    case 'verified':
      return 'Identity verified successfully!';
    case 'failed':
      return 'Verification failed. You can try again.';
    case 'expired':
      return 'Your identity verification has expired.';
    case 'canceled':
      return 'Verification was canceled.';
    default:
      return 'Verification was canceled.';
  }
}

/**
 * Post-KYC redirect landing component.
 *
 * Polls the KYC status every 3 seconds after Stripe redirects the user back.
 * Stops polling when status changes from "pending" to a final state, or after
 * 60 seconds.
 *
 * @example
 * ```tsx
 * const { fetchStatus } = useKyc();
 * <KycCallback fetchStatus={fetchStatus} onComplete={(status) => navigate('/dashboard')} />
 * ```
 */
export function KycCallback({ fetchStatus, onComplete, className }: KycCallbackProps) {
  const [status, setStatus] = useState<string | null>(null);
  const [timedOut, setTimedOut] = useState(false);

  const onCompleteRef = useRef(onComplete);
  const fetchStatusRef = useRef(fetchStatus);

  useEffect(() => {
    onCompleteRef.current = onComplete;
    fetchStatusRef.current = fetchStatus;
  }, [onComplete, fetchStatus]);

  useEffect(() => {
    let cancelled = false;
    let intervalId: ReturnType<typeof setInterval> | null = null;
    const timeoutId = setTimeout(() => {
      setTimedOut(true);
      if (intervalId !== null) clearInterval(intervalId);
    }, POLL_TIMEOUT_MS);

    const poll = async () => {
      try {
        const resp = await fetchStatusRef.current();
        if (cancelled) return;
        setStatus(resp.status);
        if (resp.status !== 'pending') {
          clearTimeout(timeoutId);
          if (intervalId !== null) clearInterval(intervalId);
          onCompleteRef.current?.(resp.status);
        }
      } catch {
        // fetchStatus sets its own error state; swallow here so polling continues
      }
    };

    // Immediate first poll, then interval
    poll();
    intervalId = setInterval(poll, POLL_INTERVAL_MS);

    return () => {
      cancelled = true;
      clearTimeout(timeoutId);
      if (intervalId !== null) clearInterval(intervalId);
    };
  }, []); // stable — uses refs for callbacks

  const isPending = !status || status === 'pending';

  return (
    <div className={`cedros-kyc-callback ${className ?? ''}`} role="status" aria-live="polite">
      {timedOut && isPending ? (
        <div className="cedros-kyc-callback-content">
          <p className="cedros-kyc-callback-message">
            Verification is taking longer than expected. Please refresh or check back later.
          </p>
          {onComplete && (
            <button
              type="button"
              className="cedros-kyc-callback-continue"
              onClick={() => onComplete('pending')}
            >
              Continue
            </button>
          )}
        </div>
      ) : isPending ? (
        <div className="cedros-kyc-callback-content">
          <span className="cedros-kyc-callback-spinner" aria-hidden="true" />
          <p className="cedros-kyc-callback-message">Processing your verification...</p>
        </div>
      ) : (
        <div className="cedros-kyc-callback-content">
          <p
            className={`cedros-kyc-callback-message cedros-kyc-callback-message--${status}`}
          >
            {messageForStatus(status!)}
          </p>
          {onComplete && (
            <button
              type="button"
              className="cedros-kyc-callback-continue"
              onClick={() => onComplete(status!)}
            >
              Continue
            </button>
          )}
        </div>
      )}
    </div>
  );
}
